class Solution {
public:
    int countStaircase(vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;                     // answer may exceed 32‑bit
        unordered_map<int,int> freq;
        unordered_map<int,int> rank;
        for (int L = 0; L < n; ++L) {
            freq.clear();
            rank.clear();
            int distinct = 0;
            int bad = 0;                       // #values whose freq != required rank
            for (int R = L; R < n; ++R) {
                int x = nums[R];
                int f = ++freq[x];
                if (rank.find(x) == rank.end()) {          // first time we see x in this window
                    ++distinct;
                    rank[x] = distinct;                    // required frequency
                    if (f != rank[x]) ++bad;                // mismatch unless rank==1
                } else {
                    int req = rank[x];
                    if (f - 1 == req) ++bad;                // was matching, now mismatching
                    if (f == req) --bad;                    // now matches
                }
                if (freq[x] > rank[x]) break;               // cannot be repaired
                if (bad == 0) ++ans;                        // valid staircase
            }
        }
        return (int)ans;
    }
};
